import path from 'path';
import fs from 'fs';
import RedisClient from './redisClient.js';

// This util is used to flush all redis keys "clientAssetCache:*". Those keys point to code chunks that are compiled FE
// assets generated by uiServer.js, and cached to redis for quick repeat serves.
class MigrateRDB {

    constructor() {
        const self = this;
        self.initRedisClient(() => {
            self.findAndDeleteClientAssetCache(() => {
                process.exit();
            });
        });
    }

    initRedisClient(cback) {
        const self = this;
        self.redisClient = new RedisClient({
            onConnect: (client) => {
                console.log('Connected new redis client for hbFlushServerCache.');
                if (cback) cback();
            }
        });
    }

    findAndDeleteClientAssetCache(cback) {
        const self = this;
        const cacheKeyPattern = 'clientAssetCache:*';
        self.redisClient.keys(cacheKeyPattern, (foundKeys, err) => {
            if (!foundKeys || foundKeys.length === 0 || err) {
                console.log(`Could not find data at redis keys: ${cacheKeyPattern}`, err);
                if (cback) cback();
                return;
            }
            let keysDeleted = 0;
            foundKeys.forEach((thisKey) => {
                self.redisClient.del(thisKey, (removedCount, err) => {
                    ++keysDeleted;
                    if (!removedCount || err) {
                        console.error(`Could not delete cached FE asset at redis key: ${thisKey}`, err);
                    } else {
                        console.log(`Deleted cached FE asset at redis key: ${thisKey}`);
                    }
                    if (keysDeleted === foundKeys.length && cback) cback();
                });
            });
        });
    }

}

const migrateRDB = new MigrateRDB();
export default MigrateRDB;
